struct List { head: Option<Int>, tail: Option<Box<List>> }

fn walk_list(l: List) -> Int {
    let mut total = 0
    let mut current = Some(l)
    while letSome(node) == current {
        match node.head {
            Some(x) => {
                if x % 2 == 0 {
                    total = total + x
                } else {
                    print(x * 2)
                }
            },
            None => break_,
        }
        current = node.tail
    }
    total
}

